/* C0/91AC  acceleration / auto-target integrator + subpixel->pixel converter.
   m=1 (A is 8-bit) the WHOLE time -- every ADC/LSR/EOR/INC below is 8-bit, wraparound mod 256.
   All $XX are r[0x1D00+XX].  $0400,$01BC are absolute r[0x0400],r[0x01BC].
   Signed bytes are int8_t; arithmetic that "wraps" is uint8_t. TSB sets bits, BIT tests AND. */

void Ct_AccelIntegrate(uint8_t* r) {
  uint8_t* d = r + 0x1D00;          /* direct page base */

  /* ---------- (1) AUTO-TARGET HOLD  C0/91AC-91F6 ----------
     Only runs when an auto-walk/seek target is armed ($00 != 0).
     Drives $2E/$30 toward target ($02 -> $0A on x, $03 -> $0E on y) with a fixed +-$10 impulse.
     $01 is a 2-bit "arrived" flag (bit0=x done, bit1=y done). */
  if (d[0x00] != 0) {                                  /* 91AC BEQ 91F8 */
    /* X axis: compare current x ($02) to target x ($0A) -- NOTE both are unsigned CMP */
    if (d[0x02] == d[0x0A]) {                          /* 91B4 BEQ 91C4 : arrived on x? */
      if ((d[0x87] & 0x0F) != 0) {                     /* 91C4: $87 low nibble = subpixel x phase */
        d[0x2E] = 0xF0;                                /* 91BE: not settled -> nudge -1px (-$10) */
      } else {
        /* 91CA TSB $01 with #$01 : set x-arrived bit (and leave $2E at its seeded value) */
        d[0x01] |= 0x01;
      }
    } else if (d[0x02] < d[0x0A]) {                    /* 91B6 BCC 91BE : need to move +x */
      d[0x2E] = 0xF0;                                  /* 91BE: -1px  (sign chosen by game's coord convention) */
    } else {                                           /* $02 > $0A : 91B8 */
      d[0x2E] = 0x10;                                  /* +1px */
    }
    /* Y axis: identical structure, target $0E, phase byte $89, output $30, arrived-bit #$02 */
    if (d[0x03] == d[0x0E]) {                          /* 91D2 */
      if ((d[0x89] & 0x0F) != 0) d[0x30] = 0xF0;       /* 91E2/91DC */
      else d[0x01] |= 0x02;                            /* 91E8 TSB $01,#$02 */
    } else if (d[0x03] < d[0x0E]) {                    /* 91D4 BCC 91DC */
      d[0x30] = 0xF0;                                  /* 91DC */
    } else {
      d[0x30] = 0x10;                                  /* 91D6 */
    }
    if (d[0x01] == 0x03) {                             /* 91EC: both axes arrived */
      d[0x00] = 0x02;                                  /* advance auto-target state machine */
      d[0x01] = 0x00;                                  /* clear arrived flags */
    }
  }

  /* ---------- (2) FORCED-VECTOR IMPULSE DECODE  C0/91F8-9236 ----------
     Active only in knockback/auto-vector mode ($01BC != 0). Builds two signed impulse
     bytes $4E (x) and $4F (y) from control word $0400. When inactive, $4E/$4F keep
     whatever they held; they are still ADDed below, so the caller must clear them when
     not in this mode (see UNCERTAINTY). */
  if (r[0x01BC] != 0) {                                /* 91F8 BEQ 9238 */
    uint8_t c = r[0x0400];
    if (c & 0x01) {                                    /* 9200 BIT #$01 : sign = negative */
      /* magnitude from bit2 (x): (c&4)<<2 = 0 or 0x10 ; then negate */
      d[0x4E] = (uint8_t)(-(uint8_t)(((c & 0x04) << 2))); /* 9216-921D EOR FF/INC */
      /* magnitude from bit1 (y): (c&2)<<3 = 0 or 0x10 ; then negate */
      d[0x4F] = (uint8_t)(-(uint8_t)(((r[0x0400] & 0x02) << 3)));
    } else {                                           /* positive */
      d[0x4E] = (uint8_t)((c & 0x04) << 2);            /* 0 or 0x10  (9204-9208) */
      d[0x4F] = (uint8_t)((r[0x0400] & 0x02) << 3);    /* 0 or 0x10  (920A-9212) */
    }
    if (d[0x0A] == 0) d[0x4E] = 0;                     /* 922C: no x speed scalar -> kill x impulse */
    if (d[0x0E] == 0) d[0x4F] = 0;                     /* 9232: no y speed scalar -> kill y impulse */
  }
  /* else: $4E/$4F untouched (fall straight to 9238). */

  /* ---------- (3) INTEGRATE INTO 8.4 SUBPIXEL ACCUMULATORS  C0/9238-92C8 ----------
     Each accumulator is a signed 8-bit fixed-point value with 4 fractional bits (range -8.0..+7.9375 px).
     Channel 1 (always): x=$3B, y=$3C.   Add frame impulse + accel bias + forced impulse. */
  d[0x3B] = (uint8_t)(d[0x2E] + d[0x3B] + d[0x24] + d[0x4E]);   /* 9238-9243 (3 CLC/ADC, 8-bit) */
  d[0x3C] = (uint8_t)(d[0x30] + d[0x3C] + d[0x25] + d[0x4F]);   /* 9245-9250 */

  /* Channel 2: x=$3D, y=$3E.  $36 bit1 picks the source. */
  if (d[0x36] & 0x02) {                                /* 9252 BIT #$02 */
    d[0x3D] = (uint8_t)(d[0x37] + d[0x3D] + d[0x26]);            /* 9258-9260 : use stored vector $37 */
    d[0x3E] = (uint8_t)(d[0x38] + d[0x3E] + d[0x27]);            /* 9262-926A */
  } else {                                             /* 926E: mirror the live frame impulse */
    d[0x3D] = (uint8_t)(d[0x2E] + d[0x37] + d[0x3D] + d[0x26] + d[0x4E]);  /* 926E-927C */
    d[0x3E] = (uint8_t)(d[0x30] + d[0x38] + d[0x3E] + d[0x27] + d[0x4F]);  /* 927E-928C */
  }

  /* Channel 3: x=$3F, y=$40.  $36 bit2 picks the source. */
  if (d[0x36] & 0x04) {                                /* 928E BIT #$04 */
    d[0x3F] = (uint8_t)(d[0x39] + d[0x3F] + d[0x28]);            /* 9294-929C */
    d[0x40] = (uint8_t)(d[0x3A] + d[0x40] + d[0x29]);            /* 929E-92A6 */
  } else {                                             /* 92AA */
    d[0x3F] = (uint8_t)(d[0x2E] + d[0x39] + d[0x3F] + d[0x28] + d[0x4E]);  /* 92AA-92B8 */
    d[0x40] = (uint8_t)(d[0x30] + d[0x3A] + d[0x40] + d[0x29] + d[0x4F]);  /* 92BA-92C8 */
  }

  /* ---------- (4) SUBPIXEL -> SIGNED-SPLIT INTEGER PIXELS  C0/92CA-93CA ----------
     For each of the 6 accumulators ($3B,$3C,$3D,$3E,$3F,$40), in this exact order:
       pixels = |acc| >> 4  (arithmetic on the ABSOLUTE value: negatives are EOR FF/INC = two's-complement
                             negate to a magnitude FIRST, THEN >>4 four times -> logical shift of the magnitude).
       if acc >= 0 (BMI not taken): POS slot = pixels, NEG slot = 0.
       if acc <  0:                  NEG slot = pixels, POS slot = 0.
       remainder = sign-extended low nibble of the ORIGINAL acc:
           if (acc & 0x0F)==0 -> 0
           else if acc>=0     -> acc & 0x0F           (0..7, +)
           else               -> acc | 0xF0           (0xF8..0xFF, sign-extended -, i.e. -8..-1)
       acc := remainder   (carries subpixels to next frame; this is the real momentum/inertia store).
     Slot map (NEG,POS) = (low addr, high addr) per pair:
       $3B -> $41(-x) $42(+x)
       $3C -> $43(-y) $44(+y)
       $3D -> $45     $46     (channel 2 x)
       $3E -> $47     $48     (channel 2 y)
       $3F -> $49     $4A     (channel 3 x)
       $40 -> $4B     $4C     (channel 3 y)  */
  for (int k = 0; k < 6; ++k) {
    static const uint8_t accAddr[6] = {0x3B,0x3C,0x3D,0x3E,0x3F,0x40};
    static const uint8_t negSlot[6] = {0x41,0x43,0x45,0x47,0x49,0x4B};
    static const uint8_t posSlot[6] = {0x42,0x44,0x46,0x48,0x4A,0x4C};
    uint8_t a = d[accAddr[k]];
    if ((int8_t)a < 0) {                                /* BMI taken */
      uint8_t mag = (uint8_t)(-a);                      /* EOR FF / INC A : two's-complement magnitude */
      d[negSlot[k]] = (uint8_t)(mag >> 4);              /* 4x LSR (8-bit) */
      d[posSlot[k]] = 0;
    } else {
      d[posSlot[k]] = (uint8_t)(a >> 4);
      d[negSlot[k]] = 0;
    }
    /* fractional remainder, sign-extended to 8 bits, written back over the accumulator */
    if ((a & 0x0F) == 0)          d[accAddr[k]] = 0;
    else if ((int8_t)a >= 0)      d[accAddr[k]] = (uint8_t)(a & 0x0F);     /* BPL -> AND #$0F */
    else                          d[accAddr[k]] = (uint8_t)(a | 0xF0);     /* ORA #$F0 */
  }

  /* ---------- (5) ACCEL-BIAS TIMEOUT  C0/93CC-93E0 ----------
     $4D is a frame countdown for the standing acceleration bias. When it ticks from 1 to 0,
     wipe the bias bytes $24..$29 so the actor stops accelerating. */
  if (d[0x4D] != 0) {                                   /* 93CC BEQ 93E0 */
    if (--d[0x4D] == 0) {                               /* 93D0 DEC, BNE 93E0 */
      d[0x24] = d[0x25] = d[0x26] = d[0x27] = d[0x28] = d[0x29] = 0;  /* 93D4-93DE */
    }
  }
  /* 93E0 RTS -- control returns to C0/8855 which falls into the 93E1 collision/step tree
     that consumes $41..$4C. */
}
